{
  "name": "管道进程流接口",
  "name_en": "Piped Process Stream Interface",
  "manufacturer": "",
  "description": "一个非物理的软件流接口组件，通过子进程的标准输入/输出进行字节流通信。在实验系统中可用于把协议栈、控制工具或辅助进程接入数据通道，负责读写和关闭进程管道流。",
  "description_en": "A non-physical software stream interface component that communicates over a child process's standard input/output as a byte stream. In laboratory systems, it can be used to connect protocol stacks, control utilities, or helper processes into a data path, providing stream write, read, and close operations.",
  "actions": [
    {
      "action_name": "auto-write",
      "description": "向管道进程流写入数据。",
      "description_en": "Write data to the piped process stream."
    },
    {
      "action_name": "auto-read",
      "description": "从管道进程流读取数据。",
      "description_en": "Read data from the piped process stream."
    },
    {
      "action_name": "auto-close",
      "description": "关闭管道进程流。",
      "description_en": "Close the piped process stream."
    }
  ],
  "tag_hints": [
    "piped process communication",
    "stdin/stdout stream",
    "IPC byte stream",
    "process I/O",
    "protocol helper",
    "generic stream interface"
  ]
}

